+
+                this.masterEpoch = newMasterEpoch;
+
+                // Change sync state set
+                final HashSet<String> newSyncStateSet = new HashSet<>();
+                newSyncStateSet.add(this.localAddress);
+                changeSyncStateSet(newSyncStateSet, syncStateSetEpoch);
