+    private void initConnectionMetrics() {
+        producerConnection = brokerMeter.gaugeBuilder(GAUGE_PRODUCER_CONNECTIONS)
+            .setDescription("Producer connections")
+            .ofLongs()
+            .buildWithCallback(measurement -> {
