+                        .put(LABEL_LANGUAGE, attr.language.name().toLowerCase())
+                        .put(LABEL_VERSION, MQVersion.getVersionDesc(attr.version).toLowerCase())
+                        .put(LABEL_CONSUME_MODE, attr.consumeMode.getTypeCN().toLowerCase())
