+    private static class Key {
+        private final String topic;
+        private final String group;
+        private final int queueId;
+
+        public Key(String topic, String group, int queueId) {
+            this.topic = topic;
+            this.group = group;
+            this.queueId = queueId;
+        }
+
+        @Override
+        public boolean equals(Object o) {
+            if (this == o) {
