+            }
+            if (o == null || getClass() != o.getClass()) {
+                return false;
+            }
+            Key key = (Key) o;
+            return queueId == key.queueId && Objects.equal(topic, key.topic) && Objects.equal(group, key.group);
+        }
+
+        @Override
+        public int hashCode() {
