+                } catch (Throwable throwable) {
+                    logger.error("[Bug]TieredDispatcher#dispatchByMQContainer: dispatch failed, can not dispatch by container: topic: {}, queueId: {}", topic, queueId, throwable);
+                }
+            });
+        }
+    }
