+                long queueOffset;
+                if (lastRequestIsExpired) {
+                    queueOffset = nextBeginOffset;
+                    container.decreaseReadAheadFactor();
+                } else {
+                    queueOffset = maxOffsetOfLastRequest + 1;
+                    container.increaseReadAheadFactor();
+                }
