+                List<Pair<Integer, CompletableFuture<Long>>> futureList = new ArrayList<>();
+                long nextQueueOffset = queueOffset;
+                if (flag == 1) {
+                    int firstBatchSize = factor % storeConfig.getReadAheadBatchSizeFactorThreshold() * maxMsgNums;
