+        this.messageQueue = messageQueue;
+        this.storeConfig = storeConfig;
+        this.fileQueue = new TieredFileQueue(TieredFileSegment.FileSegmentType.COMMIT_LOG, messageQueue, storeConfig);
+        if (fileQueue.getBaseOffset() == -1) {
