+    public static final int MSG_LEN = 4 //TOTALSIZE
+        + 4 //MAGICCODE
+        + 4 //BODYCRC
+        + 4 //QUEUEID
+        + 4 //FLAG
+        + 8 //QUEUEOFFSET
+        + 8 //PHYSICALOFFSET
+        + 4 //SYSFLAG
