+        + 8 //BORNHOST
+        + 8 //STORETIMESTAMP
+        + 8 //STOREHOSTADDRESS
+        + 4 //RECONSUMETIMES
+        + 8 //Prepared Transaction Offset
+        + 4 + 0 //BODY
+        + 2 + 0 //TOPIC
+        + 2 + 30 //properties
+        + 0;
+
+    public static ByteBuffer buildMessageBuffer() {
+        // Initialization of storage space
+        ByteBuffer buffer = ByteBuffer.allocate(MSG_LEN);
+        // 1 TOTALSIZE
+        buffer.putInt(MSG_LEN);
+        // 2 MAGICCODE
+        buffer.putInt(MessageDecoder.MESSAGE_MAGIC_CODE_V2);
+        // 3 BODYCRC
+        buffer.putInt(3);
+        // 4 QUEUEID
+        buffer.putInt(4);
+        // 5 FLAG
+        buffer.putInt(5);
+        // 6 QUEUEOFFSET
+        buffer.putLong(6);
+        // 7 PHYSICALOFFSET
+        buffer.putLong(7);
+        // 8 SYSFLAG
+        buffer.putInt(8);
+        // 9 BORNTIMESTAMP
+        buffer.putLong(9);
+        // 10 BORNHOST
+        buffer.putLong(10);
+        // 11 STORETIMESTAMP
+        buffer.putLong(11);
+        // 12 STOREHOSTADDRESS
+        buffer.putLong(10);
+        // 13 RECONSUMETIMES
+        buffer.putInt(13);
+        // 14 Prepared Transaction Offset
+        buffer.putLong(14);
+        // 15 BODY
+        buffer.putInt(0);
+        // 16 TOPIC
+        buffer.putShort((short) 0);
+        // 17 PROPERTIES
+        Map<String, String> map = new HashMap<>();
+        map.put(MessageConst.PROPERTY_UNIQ_CLIENT_MESSAGE_ID_KEYIDX, "uk");
+        map.put("userkey", "uservalue0");
+        String properties = MessageDecoder.messageProperties2String(map);
+        byte[] propertiesBytes = properties.getBytes(StandardCharsets.UTF_8);
+        buffer.putShort((short) propertiesBytes.length);
+        buffer.put(propertiesBytes);
+        buffer.flip();
+
+        Assert.assertEquals(MSG_LEN, buffer.remaining());
+        return buffer;
+    }
+
+    @Test
