+        fileSegmentLock.writeLock().lock();
+        try {
+            for (int i = 0; i < fileSegmentList.size(); i++) {
+                try {
+                    TieredFileSegment fileSegment = fileSegmentList.get(i);
+                    if (needToDeleteSet.contains(fileSegment.getBaseOffset())) {
+                        fileSegment.close();
